```

Final Code:
public class HelloWorld {
    public static void main(String[] args) {
        String message = "Hello World!";
        int gridSize = 5;
        String[][] grid = new String[gridSize][gridSize];

        int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}}; // right, down, left, up
        int currentDirection = 0;
        int x = 0;
        int y = 0;
        int index = 0;

        while (index < message.length()) {
            grid[x][y] = String.valueOf(message.charAt(index));
            int nextX = x + directions[currentDirection][0];
            int nextY = y + directions[currentDirection][1];

            if (nextX < 0 || nextX >= gridSize || nextY < 0 || nextY >= gridSize || grid[nextX][nextY] != null) {
                currentDirection = (currentDirection + 1) % 4;
                nextX = x + directions[currentDirection][0];
                nextY = y + directions[currentDirection][1];
            }

            x = nextX;
            y = nextY;
            index++;
        }

        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                if (grid[i][j] == null) {
                    System.out.print(" ");
                } else {
                    System.out.print(grid[i][j]);
                }
            }
            System.out.println();
        }
    }
}

