    std::vector<std::string> results;
    for (const auto& snippet : snippets) {
        bool identified = false;
        for (const auto& [keyword, language] : language_map) {
            if (snippet.find(keyword) != std::string::npos) {
                results.push_back(language);
                identified = true;
                break;
            }
        }
        if (!identified) {
            results.push_back("Unknown");
        }
    }

    return results;
}

int main() {
    std::vector<std::string> snippets = {
        "#include<bits/stdc++.h>\nusing namespace std;\nint main() { cout << \"Hello, World\"; return 0; }",
        "import sys\nprint(\"Hello, World\")",
        "#include <iostream>\nusing namespace std;\nint main() { cout << \"Hello, World\"; return 0; }",
        "#include <stdio.h>\nint main() { printf(\"Hello, World\"); return 0; }",
        "console.log(\"Hello, World\");",
        "public class Main { public static void main(String[] args) { System.out.println(\"Hello, World\"); } }",
        "package main\nimport \"fmt\"\nfunc main() { fmt.Println(\"Hello, World\") }",
        "print(\"Hello, World\")",
        "puts \"Hello, World\"",
        "<?php echo \"Hello, World\"; ?>"
    };

    std::vector<std::string> results = identify_languages(snippets);
    for (const auto& result : results) {
        std::cout << result << std::endl;
    }

    return 0;
}

