function evaluateExpression(expression, xValue):
    terms = split(expression, ' ')
    result = 0
    for term in terms:
        if term contains 'x':
            coefficient = extractCoefficient(term)
            power = extractPower(term)
            result += coefficient * (xValue ** power)
        else:
            result += convertToInteger(term)
    return result

function extractCoefficient(term):
    if term starts with '+':
        return convertToInteger(term[1:])
    elif term starts with '-':
        return -convertToInteger(term[1:])
