def evaluate_expression(expression, x_value):
    terms = expression.replace('-', '+-').split('+')
    result = 0
    for term in terms:
        term = term.strip()
        if term:
            if 'x' in term:
                if term.startswith('x'):
                    coefficient = 1
                elif term.startswith('-x'):
                    coefficient = -1
                else:
                    coefficient = int(term[:term.index('x')])

                if '^' in term:
                    power = int(term[term.index('^') + 1:])
                else:
                    power = 1

                result += coefficient * (x_value ** power)
            else:
                result += int(term)
    return result

# Example usage:
