            span.textContent = textInfo.text;
            span.style.color = textInfo.color;
            span.style.marginRight = '20px';
            document.getElementById('blinking-container').appendChild(span);

            function blink() {
                span.style.visibility = (span.style.visibility === 'hidden' ? '' : 'hidden');
                setTimeout(blink, textInfo.interval);
            }

            blink();
        }

        blinkingTexts.forEach(createBlinkingText);
    </script>
