    n = len(lst)
    for i in range(n):
        for j in range(0, n-i-1):
            if lst[j] > lst[j+1]:
                lst[j], lst[j+1] = lst[j+1], lst[j]

    # Remove duplicates
    new_list = []
    for i in range(n):
        if i == 0 or lst[i] != lst[i-1]:
