public class StringComparison {
    public static int compareStrings(String s1, String s2) {
        String s1Lower = s1.toLowerCase();
        String s2Lower = s2.toLowerCase();

        if (s1Lower.equals(s2Lower)) {
            return 0;
        } else if (s1Lower.contains(s2Lower)) {
            return 2;
        } else if (s2Lower.contains(s1Lower)) {
            return -2;
        } else if (s1Lower.compareTo(s2Lower) < 0) {
            return -1;
        } else {
            return 1;
        }
    }

    public static void main(String[] args) {
        System.out.println(compareStrings("Hello", "hello")); // Output: 0
        System.out.println(compareStrings("Hello", "Goodbye")); // Output: -1
        System.out.println(compareStrings("Goodbye", "Hello")); // Output: 1
        System.out.println(compareStrings("Hello", "HelloWorld")); // Output: 2
        System.out.println(compareStrings("HelloWorld", "Hello")); // Output: -2
    }
}

