import psycopg2
from threading import Thread
import socket

def initialize_server():
    setup_database_connection()
    start_multi_threaded_server()

def setup_database_connection():
    global conn
    conn = psycopg2.connect(
        dbname="your_dbname",
        user="your_username",
        password="your_password",
        host="your_host"
    )

def start_multi_threaded_server():
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.bind(('localhost', 9999))
    server_socket.listen(5)
    print("Server started, waiting for connections...")

    while True:
        client_socket, addr = server_socket.accept()
        print(f"Connected to {addr}")
        Thread(target=handle_client_request, args=(client_socket,)).start()

def handle_client_request(client_socket):
    try:
        request = client_socket.recv(1024).decode('utf-8')
        request_type, query_or_transaction = request.split('|')

        if request_type == "READ":
            result = execute_read_query(query_or_transaction)
            client_socket.send(result.encode('utf-8'))
        elif request_type == "WRITE":
            execute_write_transaction(query_or_transaction)
            client_socket.send("Transaction successful".encode('utf-8'))
    except Exception as e:
        client_socket.send(str(e).encode('utf-8'))
    finally:
        client_socket.close()

def execute_read_query(query):
