1. Parse the input string and use a stack to keep track of characters and their counts.
2. Traverse the string, updating the stack with the current character and its count.
3. If a character appears three times consecutively, remove it from the stack.
4. Reconstruct the string from the stack.

Pseudo-code:
```
function removeAdjacentDuplicatesWithLimit(str):
    initialize empty stack
    for each character c in str:
        if stack is empty or top of stack character != c:
            push (c, 1) to stack
        else:
            increment count of top of stack
            if count of top of stack >= 3:
                pop from stack
    result = ""
    for each (char, count) in stack:
        append char * count to result
    return result
```

Final Code:
using System;
using System.Collections.Generic;

class Program
{
    static string removeAdjacentDuplicatesWithLimit(string str)
    {
        Stack<(char, int)> stack = new Stack<(char, int)>();

        foreach (char c in str)
        {
            if (stack.Count == 0 || stack.Peek().Item1 != c)
            {
                stack.Push((c, 1));
            }
            else
            {
                var top = stack.Pop();
                if (top.Item2 + 1 < 3)
                {
                    stack.Push((c, top.Item2 + 1));
                }
            }
        }

        List<char> result = new List<char>();
        foreach (var item in stack)
        {
            for (int i = 0; i < item.Item2; i++)
            {
                result.Add(item.Item1);
            }
        }

        return new string(result.ToArray());
    }

    static void Main()
    {
        string str = "aabbccddd";
        Console.WriteLine(removeAdjacentDuplicatesWithLimit(str)); // Output: "aabbcc"
    }
}

