#include <iostream>
#include <string>
using namespace std;

// Function to demonstrate printing pyramid pattern
void pyramidPattern(int levels) {
    // Outer loop to handle number of levels
    for (int level = 1; level <= levels; level++) {
        int numX = 2 * level - 1;
        int numSpaces = (2 * levels - 1) - numX;

        // Print leading spaces
        for (int i = 0; i < numSpaces / 2; i++) {
            cout << " ";
        }

        // Print 'x' characters
        for (int j = 0; j < numX; j++) {
            cout << "x";
        }

        // Print trailing spaces
        for (int k = 0; k < numSpaces / 2; k++) {
            cout << " ";
        }

        // Ending line after each row
        cout << "\n";
    }
}

// Driver Function
