#include <iostream>
#include <sstream>
#include <vector>
#include <algorithm>
#include <cctype>

using namespace std;

string reverseWordsWithPunctuation(const string& input) {
    istringstream iss(input);
    vector<string> words;
    string word;
    while (iss >> word) {
        if (!word.empty() && ispunct(word.back())) {
            string coreWord = word.substr(0, word.size() - 1);
            char punctuation = word.back();
            reverse(coreWord.begin(), coreWord.end());
            words.push_back(coreWord + punctuation);
        } else {
            reverse(word.begin(), word.end());
            words.push_back(word);
        }
    }
    ostringstream oss;
    for (size_t i = 0; i < words.size(); ++i) {
        if (i != 0) {
            oss << " ";
        }
        oss << words[i];
    }
    return oss.str();
}

int main() {
    string s = "Hello World!";
    string result = reverseWordsWithPunctuation(s);
    cout << result; // Outputs: !olleH !dlroW
    return 0;
}

