      isSubmitEnabled: false,
    };
  }

  validateName = (name) => {
    if (name.trim() === '') {
      return 'Name is required.';
    }
    return '';
  };

  validateAge = (age) => {
    const ageNumber = parseInt(age, 10);
    if (isNaN(ageNumber) || ageNumber <= 0) {
      return 'Age must be a positive integer.';
    }
    return '';
  };

  handleChange = (event) => {
    const target = event.target;
    const value = target.type === 'checkbox' ? target.checked : target.value;
    const name = target.name;

    let nameError = this.state.nameError;
    let ageError = this.state.ageError;

    if (name === 'name') {
      nameError = this.validateName(value);
    } else if (name === 'age') {
      ageError = this.validateAge(value);
    }

    const isSubmitEnabled = nameError === '' && ageError === '';

    this.setState({
      [name]: value,
      nameError,
      ageError,
      isSubmitEnabled,
    });
  };

  handleSubmit = (event) => {
    event.preventDefault();
    // Handle form submission
    console.log('Form submitted:', this.state);
  };

  render() {
    return (
      <form onSubmit={this.handleSubmit}>
        <label>
          Name:
          <input type="text" name="name" value={this.state.name} onChange={this.handleChange} />
          {this.state.nameError && <div style={{ color: 'red' }}>{this.state.nameError}</div>}
        </label>
        <br />
        <label>
          Age:
          <input type="text" name="age" value={this.state.age} onChange={this.handleChange} />
          {this.state.ageError && <div style={{ color: 'red' }}>{this.state.ageError}</div>}
        </label>
        <br />
        <button type="submit" disabled={!this.state.isSubmitEnabled}>Submit</button>
      </form>
    );
  }
}

