import java.util.ArrayList;
import java.util.List;

public class WordExtractor {
    public static List<String> getWords(String sentence) {
        List<String> words = new ArrayList<>();
        String[] wordsArray = sentence.split("\\s+");
        for (String word : wordsArray) {
            String cleanedWord = word.replaceAll("[^a-zA-Z0-9]", "");
            if (!cleanedWord.isEmpty()) {
                words.add(cleanedWord);
            }
        }
        return words;
    }

    public static void main(String[] args) {
        String sentence = "I am a student, learning Java!";
        List<String> result = getWords(sentence);
        System.out.println(result); // Output: [I, am, a, student, learning, Java]
    }
}

