import heapq

def huffman_encode(strings):
    combined_string = ''.join(strings)
    freq = {}
    for c in combined_string:
        freq[c] = freq.get(c, 0) + 1

    heap = [[weight, [char, ""]] for char, weight in freq.items()]
    heapq.heapify(heap)

    while len(heap) > 1:
        low = heapq.heappop(heap)
        high = heapq.heappop(heap)
        for pair in low[1:]:
            pair[1] = '0' + pair[1]
        for pair in high[1:]:
            pair[1] = '1' + pair[1]
        heapq.heappush(heap, [low[0] + high[0]] + low[1:] + high[1:])

    codebook = {char: code for char, code in heap[0][1:]}
    encoded_strings = [''.join(codebook[char] for char in string) for string in strings]

    return codebook, encoded_strings

if __name__ == '__main__':
    strings = ["aaaaaaaaabcc", "ddddee", "ffgghh"]
    codes, encoded = huffman_encode(strings)
    print("Codebook:", codes)
    print("Encoded Strings:", encoded)

