using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static void Main()
    {
        var listOfIntegers = new List<int> { 1, 2, 3, 3, 2, 2, 3, 4, 5, 5, 5, 6 };

        // Step 2: Create a dictionary to store the frequency of each integer
        var frequencyDict = new Dictionary<int, int>();

        // Step 3: Populate the dictionary with frequencies
        foreach (var number in listOfIntegers)
        {
            if (frequencyDict.ContainsKey(number))
            {
                frequencyDict[number]++;
            }
            else
            {
                frequencyDict[number] = 1;
            }
        }

        // Step 4: Sort the dictionary entries by frequency in descending order and by integer value in ascending order for ties
        var sortedFrequencies = frequencyDict.ToList();
        sortedFrequencies.Sort((pair1, pair2) =>
        {
            if (pair1.Value != pair2.Value)
            {
                return pair2.Value.CompareTo(pair1.Value); // Descending order of frequency
            }
            else
            {
                return pair1.Key.CompareTo(pair2.Key); // Ascending order of integer value
            }
        });

        // Step 5: Print the sorted list of integers with their frequencies
        foreach (var pair in sortedFrequencies)
        {
            Console.WriteLine($"Element: {pair.Key}, Frequency: {pair.Value}");
        }
    }
}

