import java.util.HashMap;
import java.util.Map;

class Node implements Cloneable {
    Node next;
    Node prev;
    int value;

    public Node(int value) {
        this.value = value;
    }

    @Override
    protected Node clone() throws CloneNotSupportedException {
        return (Node) super.clone();
    }
}

public class DeepCopyExample {

    public static Node deepCopy(Node originalObject, Map<Node, Node> clonedObjectsMap) throws CloneNotSupportedException {
        if (originalObject == null) {
            return null;
        }
        if (clonedObjectsMap.containsKey(originalObject)) {
            return clonedObjectsMap.get(originalObject);
        }

        Node newObject = originalObject.clone();
        clonedObjectsMap.put(originalObject, newObject);

        newObject.next = deepCopy(originalObject.next, clonedObjectsMap);
        newObject.prev = deepCopy(originalObject.prev, clonedObjectsMap);

        return newObject;
    }

    public static void main(String[] args) {
        try {
            Node node1 = new Node(1);
            Node node2 = new Node(2);
            Node node3 = new Node(3);

            node1.next = node2;
            node2.prev = node1;
            node2.next = node3;
            node3.prev = node2;
            node3.next = node1;
            node1.prev = node3;

            Map<Node, Node> clonedObjectsMap = new HashMap<>();
            Node clonedNode1 = deepCopy(node1, clonedObjectsMap);

            // Verify that clonedNode1 is a deep copy with correct cycle structure
            System.out.println("Original node1 value: " + node1.value);
            System.out.println("Cloned node1 value: " + clonedNode1.value);
            System.out.println("Original node1 next value: " + node1.next.value);
            System.out.println("Cloned node1 next value: " + clonedNode1.next.value);
            System.out.println("Original node1 prev value: " + node1.prev.value);
            System.out.println("Cloned node1 prev value: " + clonedNode1.prev.value);
        } catch (CloneNotSupportedException e) {
            e.printStackTrace();
        }
    }
}

