public class QuickSortWithSwapCount {

    public static int quickSort(int[] arr, int low, int high) {
        if (arr == null || arr.length == 0)
            return 0;

        if (low >= high)
            return 0;

        int swapCount = 0;
        int middle = low + (high - low) / 2;
        int pivot = arr[middle];

