1. Modify the comparison in the inner loop to sort in descending order.
2. Introduce a counter to keep track of the number of swaps.
3. Return both the sorted array and the swap count.

Pseudo-code:
```
function bubbleSortDescending(array):
    n = length(array)
    swapCount = 0
    for i from 0 to n-2:
        for j from 0 to n-i-2:
            if array[j] < array[j+1]:
                swap(array[j], array[j+1])
                swapCount = swapCount + 1
    return array, swapCount
```

Final Code:
public class BubbleSort {
    public static int[] bubbleSortDescending(int[] array) {
        int n = array.length;
        int swapCount = 0;
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < n - i - 1; j++) {
                if (array[j] < array[j + 1]) {
                    int temp = array[j];
                    array[j] = array[j + 1];
                    array[j + 1] = temp;
                    swapCount++;
                }
            }
        }
        // Returning the swap count as the last element in the array
        int[] result = new int[n + 1];
        System.arraycopy(array, 0, result, 0, n);
        result[n] = swapCount;
        return result;
    }

    public static void main(String[] args) {
        int[] array = {64, 34, 25, 12, 22, 11, 90};
        int[] result = bubbleSortDescending(array);
        System.out.println("Sorted array in descending order:");
        for (int i = 0; i < result.length - 1; i++) {
            System.out.print(result[i] + " ");
        }
        System.out.println("\nTotal number of swaps: " + result[result.length - 1]);
    }
}

