#include <iostream>
#include <vector>
using namespace std;

// An iterative linear search function to search 'x' in arr[] of size 'n'
vector<int> search(int arr[], int n, int x) {
    vector<int> indices;
    for (int i = 0; i < n; i++) {
        if (arr[i] == x) {
            indices.push_back(i);
        }
    }
    return indices;
}

int main() {
    int arr[] = {2, 3, 4, 10, 40, 10, 5};
