    vector<int> result = search(arr, n, x);

    if (result.empty()) {
        cout << "Number not found";
    } else {
        cout << "Number found at indices ";
        for (size_t i = 0; i < result.size(); i++) {
            cout << result[i] << " ";
        }
    }

    return 0;
}

