#include <iostream>
#include <cstdlib>
#include <new>

size_t allocations = 0;
size_t deallocations = 0;
size_t totalMemory = 0;

void* operator new(size_t size) {
    void* ptr = std::malloc(size);
    if (!ptr) throw std::bad_alloc();
    allocations++;
    totalMemory += size;
    std::cout << "Allocated " << size << " bytes at " << ptr << std::endl;
    return ptr;
}

void operator delete(void* ptr) noexcept {
    if (ptr) {
        std::cout << "Deallocated at " << ptr << std::endl;
        deallocations++;
        // We don't know the exact size here, so we assume it's tracked elsewhere if needed.
    }
}

void reportMemoryUsage() {
    std::cout << "Memory Usage Report:" << std::endl;
    std::cout << "Total Allocations: " << allocations << std::endl;
    std::cout << "Total Deallocations: " << deallocations << std::endl;
    std::cout << "Total Memory Allocated: " << totalMemory << " bytes" << std::endl;
}

