def common_elements_with_multiplicity(arr1, arr2):
    count1 = {}
    count2 = {}

    for num in arr1:
        if num in count1:
            count1[num] += 1
        else:
            count1[num] = 1

    for num in arr2:
        if num in count2:
            count2[num] += 1
        else:
            count2[num] = 1

    result = []
    for num in count1:
        if num in count2:
            result.extend([num] * min(count1[num], count2[num]))

    return result

